void tx_data_init(){
	// ����ramʹ��
	AXI_REG_WRITE(axi_dpd_addr, TX_DATA_EN , 1) ;
	// ����״̬Ϊд
	AXI_REG_WRITE(axi_dpd_addr, TX_DATA_WR , 1) ;
	for (u32 addr=0; addr<data_len;addr++){
		// ����д�����ݼĴ�����ַ
		AXI_REG_WRITE(axi_dpd_addr, TX_DATA_ADDR  , addr) ;
		// ����д������ֵ
		AXI_REG_WRITE(axi_dpd_addr, TX_DATA_WDATA , OFDM[addr]) ;
	}
	// ����ʹ��
	AXI_REG_WRITE(axi_dpd_addr, TX_DATA_EN , 0) ;
	// ʹ��TX����
	AXI_REG_WRITE(axi_dpd_addr, TX_VLD, 1);
}

