void Reg_Write(int argc, char **argv){
	u32 addr;
	u32 wrData;

	addr   = strtoul(argv[1], NULL, 0);
	wrData = strtoul(argv[2], NULL, 0);

	AXI_REG_WRITE(axi_dpd_addr, addr * 4, wrData);
}

void Reg_Read(int argc, char **argv){
	u32 addr;
	u32 rdData;

	addr   = strtoul(argv[1], NULL, 0);
	rdData = AXI_REG_READ(axi_dpd_addr, addr * 4) ;
	XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData);
	XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData>>8);
	XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData>>16);
	XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData>>24);
}


// ��ȡCap ram����
void Cap_Data_Read(int argc, char **argv){

	u32 cap_rd_cmd;
	u32 start_addr;
	u32 stop_addr;
	u32 addr;
	u32 rdData;

	cap_rd_cmd = strtoul(argv[1], NULL, 0);
	start_addr = strtoul(argv[2], NULL, 0);
	stop_addr  = strtoul(argv[3], NULL, 0);

	// ���ö�ȡram����
	cap_rd_cmd = cap_rd_cmd + 0b1000;
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD , cap_rd_cmd) ;
	for (addr=start_addr; addr<stop_addr;addr++){
		AXI_REG_WRITE(axi_dpd_addr, CAP_RD_ADDR , addr) ;
		// ��ȡ��Ӧ����ֵ
		rdData = AXI_REG_READ(axi_dpd_addr, CAP_DATA_RDATA) ;
		XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData);
		XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData>>8);
		XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData>>16);
		XUartPs_SendByte(XPAR_XUARTPS_0_BASEADDR, rdData>>24);
	}
	// ����ʹ��
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD , 0) ;

	print("\n"); // ��ɱ�־λ
}


