// data align function
// �������
void mul(int16_t real1, int16_t imag1, int16_t real2, int16_t imag2, int64_t *real_res, int64_t *imag_res) {
    *real_res = real1 * real2 - imag1 * imag2;
    *imag_res = real1 * imag2 + imag1 * real2;
}

//// ���㸴���ķ�ֵ
double u_abs(double real, double imag) {
    return sqrt(real * real + imag * imag);
}


int dec2fixpoint(double data, double bit_width, double int_width){
	double data_fix;

	data = data * pow(2.0, bit_width - int_width);
	data_fix = floor(data);

	// data clamp
	if (data_fix < -pow(2.0, bit_width - 1)) {
		data_fix = -pow(2.0, bit_width - 1);
	} else if (data_fix > pow(2.0, bit_width - 1) - 1) {
		data_fix = pow(2.0, bit_width - 1) - 1;
	}else{
		data_fix = data_fix;
	}

	return (int)data_fix;
}


void Data_Align(int argc, char **argv){
	u32 rd_data;
	int16_t tx_i[cap_num];
	int16_t tx_q[cap_num];
	int16_t rx_i[cap_num];
	int16_t rx_q[cap_num];

	// ʱ�ӡ����ิλ
	AXI_REG_WRITE(axi_dpd_addr, DELAY , 0);

	AXI_REG_WRITE(axi_dpd_addr, APC_K_I , 0);
	AXI_REG_WRITE(axi_dpd_addr, APC_K_Q , 0);

	AXI_REG_WRITE(axi_dpd_addr, ALIGN_EN , 1);
	AXI_REG_WRITE(axi_dpd_addr, ALIGN_EN , 0);

	// ���ô�����������ֵ
	AXI_REG_WRITE(axi_dpd_addr, CAP_LEN, cap_num-1);
	AXI_REG_WRITE(axi_dpd_addr, TRIGGER_POINT, 0);

	// ʹ�ܲ���
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD, 1 << 4);
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD, 0 << 4);

	if (!dpd_wait_cap_done(1)) {
        dpd_alignment_failed("ERR ALIGN CAP_DONE_HIGH TIMEOUT\n");
        return;
    }

	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD, 1 << 5);
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD, 0 << 5);
	if (!dpd_wait_cap_done(0)) {
        dpd_alignment_failed("ERR ALIGN CAP_DONE_LOW TIMEOUT\n");
        return;
    }
	// ��ȡ����TX
	for (int ii=0; ii<cap_num;ii++){
		tx_i[ii] = OFDM[ii] ;
		tx_q[ii] = OFDM[ii] >> 16 ;
	}

	// ��ȡ����RX
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD , 0b1001) ;
	for (int ii=0; ii<cap_num;ii++){
		AXI_REG_WRITE(axi_dpd_addr, CAP_RD_ADDR , ii) ;
		// ��ȡ��Ӧ����ֵ
		rd_data = AXI_REG_READ(axi_dpd_addr, CAP_DATA_RDATA);
		rx_i[ii] = rd_data ;
		rx_q[ii] = rd_data >> 16 ;
	}
	AXI_REG_WRITE(axi_dpd_addr, CAP_DATA_CMD , 0) ;
	//--------------------------------------------------------
	// ʱ�Ӷ���
	//--------------------------------------------------------
	int64_t cor_i;
	int64_t cor_q;

	double  max_corr = 0;
	int     rx_DELAY = 0;

	// ѭ�����㻥���
	for (int d = -cap_num + 1; d < cap_num; d++) {
		cor_i = 0, cor_q = 0;  // ��ʼ������ʵ�����鲿

	// �������ʱ���µĻ����ֵ
		for (int i = 0; i < cap_num; i++) {
		 int j = i + d;
		 if (j >= 0 && j < cap_num) {
//			 int16_t tx_i = tx_data[i][0], tx_q = tx_data[i][1];
//			 int16_t rx_i = rx_data[j][0], rx_q = rx_data[j][1];

			 int64_t temp_i, temp_q;
			 mul( rx_i[j], rx_q[j], tx_i[i], -tx_q[i], &temp_i, &temp_q);  // �������
		//
			 cor_i += temp_i;
			 cor_q += temp_q;
			 }
		}
		 // ���㻥��ط�ֵ
		 double abs_corr = u_abs(cor_i, cor_q);

		// �ҵ������ط�ֵ�����Ӧʱ��
		if (abs_corr > max_corr) {
			 max_corr = abs_corr;
			 rx_DELAY = d;
		}
	}

	AXI_REG_WRITE(axi_dpd_addr, DELAY , rx_DELAY);

	//--------------------------------------------------------
	// ����У��
	//--------------------------------------------------------
	double k_i, k_q;
	double denominator = 0;
	int64_t k_temp_real, k_temp_imag;
	double molecule_real= 0, molecule_imag = 0;
	// x -> Tx , y -> Rx
	//k = np.sum(np.conj(y) * x) / np.sum(np.conj(y) * y)

	for(int ii=rx_DELAY;ii<cap_num;ii++){
		// conj(y)*y
		denominator += pow(rx_i[ii],2) + pow(rx_q[ii],2);
	}

	for(int ii = 0;ii < cap_num - rx_DELAY;ii++){
	//	double k_conj_real = Tx_p_real[i], k_conj_imag = Tx_p_imag[i];
		mul(tx_i[ii], tx_q[ii], rx_i[ii+rx_DELAY], -rx_q[ii+rx_DELAY],
				&k_temp_real, &k_temp_imag);  // �������
		molecule_real += (double)k_temp_real;
		molecule_imag += (double)k_temp_imag;
	}

	k_i = molecule_real / denominator;
	k_q = molecule_imag / denominator;

	// (32, 8)
	int k_i_fix = dec2fixpoint(k_i, 32, 8);
	int k_q_fix = dec2fixpoint(k_q, 32, 8);

	AXI_REG_WRITE(axi_dpd_addr, APC_K_I , k_i_fix);
	AXI_REG_WRITE(axi_dpd_addr, APC_K_Q , k_q_fix);

	AXI_REG_WRITE(axi_dpd_addr, ALIGN_EN , 1);
	AXI_REG_WRITE(axi_dpd_addr, ALIGN_EN , 0);

	printf("RF System Initial Successful\n");
}


// ----------------------------------------------------
// ���庯���б�
// ----------------------------------------------------
typedef void (*cmd_function)(int argc, char **argv);
typedef struct
{
	const char* name;
	cmd_function function;
	int expected_argc;
}command;

command cmd_list[] = {
	{"Reg_Write", Reg_Write, 3},
	{"Reg_Read", Reg_Read, 2},
	{"Cap_Read", Cap_Data_Read, 4},
	{"Cyclic_Write", Cyclic_Data_Write, 3},
	{"Cyclic_Read", Cyclic_Data_Read, 3},
	{"Tx_Write", TX_DATA_Write, 3},
	{"Tx_Read", Tx_Data_Read, 3},
	{"Tx_Atten", Tx_Atten, 2},
	{"Rx_Gain", Rx_Gain, 2},
	{"Data_Align", Data_Align, 1},
	{"Para_Write", Para_Write, 3},
	{"Para_Read", Para_Read, 3},
};

const char cmd_no = (sizeof(cmd_list) / sizeof(command));
unsigned char cmd = 0;

int main(void)
{
	// uart define
//	char received_cmd[] = "";
	char received_cmd[1024];
	char recvPtr[1024];
	char *token;
	int argc = 0;
	char **argv = (char **)malloc(2048 * sizeof(char *));

	//Status define
	ADI_ERR 		error;
	ad9528Device_t *AD9528_device = &clockAD9528;
	mykonosErr_t	mykError;
	const char *errorString;
	errorString = (const char*) malloc(sizeof(char) * 200);

	//static Define param
	jesd_core tx_jesd;
	jesd_core rx_jesd;

	//JESD Core Config
	tx_jesd.base_address = XPAR_JESD204_2_BASEADDR;		//BASEADDR
	tx_jesd.rx_tx_n = 0;					//TX Flag
	tx_jesd.scramble_enable = 1;
	tx_jesd.octets_per_frame = 2;			// F = 2
	tx_jesd.frames_per_multiframe = 32;		// K = 32
	tx_jesd.subclass_mode = 1;				//subclass 1

	rx_jesd.base_address = XPAR_JESD204_1_BASEADDR;		//BASEADDR
	rx_jesd.rx_tx_n = 1;					//RX Flag
	rx_jesd.scramble_enable = 1;			//
	rx_jesd.octets_per_frame = 4;			// F = 4
	rx_jesd.frames_per_multiframe = 32;		// K = 32
	rx_jesd.subclass_mode = 1;				//subclass 1

	jesd_array.tx_jesd = tx_jesd;
	jesd_array.rx_jesd = rx_jesd;
	jesd_array.orx_jesd = rx_jesd;
	jesd_array.orx_jesd.octets_per_frame = 2;	// F = 2
	jesd_array.orx_jesd.base_address=XPAR_JESD204_0_BASEADDR;

	//Cache Disable
	Xil_ICacheDisable();
	Xil_DCacheDisable();

	//platform & gpio init
	int32_t platform_status = platform_init();

	printf("platform_init status=%ld\r\n", (long)platform_status);

	if (platform_status != 0) {
		printf("STOP: platform initialization failed\r\n");
		while (1) {
		}
	}

	//GPIO Config output
	AXI_REG_WRITE(axi_lite_addr, 73 * 4, 0x7FFFF);		//rf1_gpio_t
	AXI_REG_WRITE(axi_lite_addr, 75 * 4, 0);			//rf1_gpio_o

	//AD9528 config
	AD9528_resetDevice(AD9528_device);
	error = AD9528_initDeviceDataStruct(AD9528_device,AD9528_device->pll1Settings->vcxo_Frequency_Hz,AD9528_device->pll1Settings->refA_Frequency_Hz,AD9528_device->outputSettings->outFrequency_Hz[1]);
	error = AD9528_initialize(AD9528_device);
	if (error != ADIERR_OK)
		xil_printf("WARNING: AD9528_initialize() issues. Possible cause: REF_CLK not connected.\n");
	else
		xil_printf("AD9528_initialize successful!\n");

	//request SYSREF
	no_os_gpio_direction_output(gpio_ad9528_sysref_req, 1);
	//AD9371 & JESD204B Init
	mykError = ad9371_initial(&mykDevice, jesd_array,jesd_phy_addr);
	if (mykError != MYKONOS_ERR_OK) {
		errorString = getMykonosErrorMessage(mykError);
		printf("%s", errorString);
	} else
		printf("FMC_AD9371 config successful!\n");
	//Stop SYSREF
	no_os_gpio_direction_output(gpio_ad9528_sysref_req, 0);


	//Change LO
	uint64_t tx_freq=800e6;  // 800e6 1842.48e6
	uint64_t rx_freq=800e6;  // 800e6 1747.44e6
	change_rfpll(mykDevice, TX_PLL, tx_freq);
	MYKONOS_getRfPllFrequency(&mykDevice , TX_PLL,&tx_freq);
//	change_rfpll(mykDevice, SNIFFER_PLL, tx_freq);
//	MYKONOS_getRfPllFrequency(&mykDevice , SNIFFER_PLL,&tx_freq);
	printf("tx_lo_freq=%lluHz\n", tx_freq);
	change_rfpll(mykDevice, RX_PLL, rx_freq);
	MYKONOS_getRfPllFrequency(&mykDevice , RX_PLL,&rx_freq);
	printf("rx_lo_freq=%lluHz\n", rx_freq);

	//Set RF TX & RX
	// 默认 TX 衰减为 30 dB。单位是 mdB。
	uint16_t tx1_atten_readback = 0;
	uint16_t tx2_atten_readback = 0;

	// 设置 TX1 衰减
	mykError = MYKONOS_setTx1Attenuation(&mykDevice, 20000);
	if (mykError != MYKONOS_ERR_OK) {
		printf("ERROR: set TX1 attenuation failed, code=%d\r\n",
			(int)mykError);
		while (1) {
		}
	}

	// 设置 TX2 衰减
	mykError = MYKONOS_setTx2Attenuation(&mykDevice, 20000);
	if (mykError != MYKONOS_ERR_OK) {
		printf("ERROR: set TX2 attenuation failed, code=%d\r\n",
			(int)mykError);
		while (1) {
		}
	}

	// 回读 TX1 衰减
	mykError = MYKONOS_getTx1Attenuation(&mykDevice, &tx1_atten_readback);
	if (mykError != MYKONOS_ERR_OK || tx1_atten_readback != 20000) {
		printf("ERROR: TX1 attenuation readback, code=%d, value=%u mdB\r\n",
			(int)mykError, (unsigned int)tx1_atten_readback);
		while (1) {
		}
	}

	// 回读 TX2 衰减
	mykError = MYKONOS_getTx2Attenuation(&mykDevice, &tx2_atten_readback);
	if (mykError != MYKONOS_ERR_OK || tx2_atten_readback != 20000) {
		printf("ERROR: TX2 attenuation readback, code=%d, value=%u mdB\r\n",
			(int)mykError, (unsigned int)tx2_atten_readback);
		while (1) {
		}
	}

	printf("TX attenuation verified: TX1=%u mdB, TX2=%u mdB\r\n",
		(unsigned int)tx1_atten_readback,
		(unsigned int)tx2_atten_readback);
	MYKONOS_setRx1ManualGain(&mykDevice, 195);
	MYKONOS_setRx2ManualGain(&mykDevice, 195);    // 8+195
//	MYKONOS_setObsRxManualGain(&mykDevice, OBS_RX1_TXLO, 240);
//	MYKONOS_setObsRxManualGain(&mykDevice, OBS_RX2_TXLO, 240);
//	MYKONOS_setObsRxManualGain(&mykDevice, OBS_SNIFFER_A, 240);
//	MYKONOS_setObsRxManualGain(&mykDevice, OBS_SNIFFER_B, 240);
//	MYKONOS_setObsRxManualGain(&mykDevice, OBS_SNIFFER_C, 240);
	// DPD Scene
//	MYKONOS_setTx1Attenuation(&mykDevice,6500);        // 12500
//	MYKONOS_setTx2Attenuation(&mykDevice,6500);		//12db Atlten  LNA 7000
//	MYKONOS_setRx1ManualGain(&mykDevice, 195);
//	MYKONOS_setRx2ManualGain(&mykDevice, 195);    // 8+195

	// system data initial
	tx_data_init();
	mdelay(5);
	Data_Align(argc, argv);


	while (1) {
        if (!console_get_command(received_cmd, sizeof(received_cmd))) continue;
        strcpy(recvPtr, received_cmd);
        argc = 0;
        token = strtok(recvPtr, " \t\r\n");
        while (token != NULL && argc < 16) {
            argv[argc++] = token;
            token = strtok(NULL, " \t\r\n");
        }
        argv[argc] = NULL;
        if (token != NULL) { dpd_reply("ERR ARGC\n"); continue; }
        if (argc == 0) continue;
        for (cmd = 0; cmd < cmd_no; ++cmd) {
            if (!strcmp(cmd_list[cmd].name, argv[0])) {
                if (argc != cmd_list[cmd].expected_argc) dpd_reply("ERR ARGC\n");
                else cmd_list[cmd].function(argc, argv);
                break;
            }
        }
        if (cmd == cmd_no) dpd_reply("ERR COMMAND\n");
    }
}
